import { useState } from "react";
import API_URL from "../api";

export default function UsersForm({ onAdd }) {
  const [email, setEmail] = useState("");
  const [rol, setRol] = useState("user");

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const res = await fetch(`${API_URL}/usuarios`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, rol })
      });

      if (!res.ok) {
        throw new Error(`Error al crear usuario: ${res.status} ${res.statusText}`);
      }

      setEmail("");
      setRol("user");
      onAdd();
    } catch (error) {
      console.error(error);
      alert("No se pudo guardar el usuario. Revisa que el servidor API esté disponible.");
    }
  };

  return (
    <form onSubmit={handleSubmit} className="mb-4">
      <h4>Registrar nuevo usuario</h4>

      <input
        className="form-control mb-2"
        placeholder="Email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
      />

      <select className="form-control mb-2" value={rol} onChange={(e) => setRol(e.target.value)}>
        <option value="user">Usuario</option>
        <option value="admin">Administrador</option>
      </select>

      <button className="btn btn-success">Añadir usuario</button>
    </form>
  );
}
